import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.DA9C4Pbl.js";const p=JSON.parse('{"title":"Arcsecond.local on your network","description":"","frontmatter":{"title":"Arcsecond.local on your network","visibility":"public","audience":"admin","tier":"reference","source":"generated"},"headers":[],"relativePath":"reference/network/index.md","filePath":"reference/network/index.md"}'),n={name:"reference/network/index.md"};function d(s,t,i,l,c,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="arcsecond-local-on-your-network" tabindex="-1">Arcsecond.local on your network <a class="header-anchor" href="#arcsecond-local-on-your-network" aria-label="Permalink to “Arcsecond.local on your network”">​</a></h1><p>Arcsecond.local listens on one port of your local network (5555) and on nothing from the Internet side. Everything else is outbound. One destination is required: licensing.arcsecond.io on port 443. A default installation also looks up 10 public astronomy services, all on port 443, and runs without them. The rest exists only when you turn a feature on.</p><h2 id="what-listens" tabindex="-1">What listens <a class="header-anchor" href="#what-listens" aria-label="Permalink to “What listens”">​</a></h2><ul><li>Port 5555, every interface: The application itself.</li><li>Port 8800, this machine only: The programming interface, for the arcsecond command and scripts run on the machine itself.</li><li>Port 8765, every interface: Relays webcam and all-sky camera images to the installation. Runs only when cameras are registered. Optional.</li></ul><h2 id="what-it-contacts" tabindex="-1">What it contacts <a class="header-anchor" href="#what-it-contacts" aria-label="Permalink to “What it contacts”">​</a></h2><p><strong>Required.</strong> Outbound, encrypted.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>licensing.arcsecond.io</td><td>443</td><td>Licence activation and daily check</td></tr></tbody></table><p><strong>Public catalogues and lookups.</strong> Outbound, encrypted. The installation runs without them, with less to show.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>exoplanetarchive.ipac.caltech.edu</td><td>443</td><td>Exoplanets and transits (NASA archive)</td></tr><tr><td>ogle.astrouw.edu.pl</td><td>443</td><td>Microlensing candidates (OGLE)</td></tr><tr><td>minorplanetcenter.net, cgi.minorplanetcenter.net</td><td>443</td><td>Near-Earth object candidates</td></tr><tr><td>celestrak.org</td><td>443</td><td>Satellite orbits</td></tr><tr><td>simbad.cds.unistra.fr</td><td>443</td><td>Object names and coordinates (SIMBAD)</td></tr><tr><td>timezonedb.com</td><td>443</td><td>Time-zone table refresh</td></tr><tr><td>statics.arcsecond.io</td><td>443</td><td>Sky darkness of a site</td></tr><tr><td>ssd.jpl.nasa.gov, ssd-api.jpl.nasa.gov</td><td>443</td><td>Comet and asteroid positions</td></tr><tr><td>skyview.gsfc.nasa.gov</td><td>443</td><td>Finding charts (NASA SkyView)</td></tr><tr><td>datacenter.iers.org, maia.usno.navy.mil, hpiers.obspm.fr, data.iana.org</td><td>443</td><td>Earth rotation tables</td></tr></tbody></table><p><strong>Only when you turn the feature on.</strong> Outbound. Nothing here is contacted by a default installation.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>scixplorer.org</td><td>443</td><td>Papers about a target</td></tr><tr><td>auth.gcn.nasa.gov</td><td>443</td><td>Transient alerts: sign-in</td></tr><tr><td>kafka, kafka1, kafka2, kafka3 .gcn.nasa.gov</td><td>9092</td><td>Transient alerts: the feed</td></tr><tr><td>api.tomorrow.io</td><td>443</td><td>Weather forecast</td></tr><tr><td>www.wis-tns.org</td><td>443</td><td>Transient Name Server lookups</td></tr><tr><td>a server you choose</td><td>445, 22, 21 or 443</td><td>Copies to a storage you attach</td></tr><tr><td>a server you choose</td><td>587, 465 or 25</td><td>Email through your mail server</td></tr></tbody></table><p><strong>To install and to update.</strong> Outbound, encrypted. Not needed while running.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>ghcr.io, pkg-containers.githubusercontent.com</td><td>443</td><td>Arcsecond.local itself</td></tr><tr><td>registry-1.docker.io, auth.docker.io, production.cloudflare.docker.com</td><td>443</td><td>Database and message broker</td></tr><tr><td>pypi.org, files.pythonhosted.org</td><td>443</td><td>The arcsecond command</td></tr></tbody></table><p><strong>From your users&#39; browsers.</strong> Outbound, encrypted, from their workstations, not from the installation.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>server.arcgisonline.com, tile.openstreetmap.org, global.ssl.fastly.net, api.maptiler.com</td><td>443</td><td>Map backgrounds</td></tr><tr><td>alasky.cds.unistra.fr, alaskybis.cds.unistra.fr, alasky.unistra.fr, skyview.gsfc.nasa.gov</td><td>443</td><td>Sky survey pictures</td></tr><tr><td>statics.arcsecond.io</td><td>443</td><td>Light-pollution layer, illustrations</td></tr></tbody></table><p><strong>On your local network only.</strong> Never leaves the site.</p><table tabindex="0"><thead><tr><th>Destination</th><th>Port</th><th>What for</th></tr></thead><tbody><tr><td>addresses you enter</td><td>set per device</td><td>Telescopes, domes, cameras, weather</td></tr><tr><td>a broadcast on your network</td><td>32227 (datagram)</td><td>Finding instruments on the network</td></tr><tr><td>addresses you enter</td><td>554, 80 or 443</td><td>Webcams and all-sky cameras</td></tr></tbody></table><h2 id="what-never-leaves-the-site" tabindex="-1">What never leaves the site <a class="header-anchor" href="#what-never-leaves-the-site" aria-label="Permalink to “What never leaves the site”">​</a></h2><ul><li>Images and data files</li><li>Night logs, sessions and observing conditions</li><li>Equipment configuration and instrument state</li><li>Accounts, passwords and access keys of the installation&#39;s users</li><li>Usage statistics, error reports or any other telemetry</li></ul><h2 id="if-the-connection-is-cut" tabindex="-1">If the connection is cut <a class="header-anchor" href="#if-the-connection-is-cut" aria-label="Permalink to “If the connection is cut”">​</a></h2><p>An activated installation keeps operating with no outside connection at all: instrument control and data recording are local. It only does without the lookups listed above.</p><h2 id="check-it-yourself" tabindex="-1">Check it yourself <a class="header-anchor" href="#check-it-yourself" aria-label="Permalink to “Check it yourself”">​</a></h2><ul><li>Run <code>arcsecond doctor</code> on the machine: it tests every destination above and sends nothing about your observatory. <code>arcsecond doctor --report</code> writes the result to a file for your records.</li><li>This sheet is generated from the software&#39;s own network manifest (audited 2026-10-05); the current version is at docs.arcsecond.io/reference/network.</li><li>Security questions: <a href="mailto:team@arcsecond.io" target="_blank" rel="noreferrer">team@arcsecond.io</a></li></ul><h2 id="to-print-and-to-paste" tabindex="-1">To print, and to paste <a class="header-anchor" href="#to-print-and-to-paste" aria-label="Permalink to “To print, and to paste”">​</a></h2><ul><li><a href="/network/arcsecond-local-network-sheet.pdf">The same sheet as a one-page PDF</a>.</li><li><a href="/network/network-sheet.html">The same sheet on one printable page</a>, to print from your browser.</li><li><a href="/network/firewall-request.txt">The request to send to whoever runs your firewall</a>, as plain text.</li></ul>',25)])])}const f=e(n,[["render",d]]);export{p as __pageData,f as default};
